<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Bouncing Ball Physics Playground</title>
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }
  body {
    background: #1a1a2e;
    color: #e0e0e0;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    min-height: 100vh;
    overflow: hidden;
  }
  h1 {
    font-size: 1.4rem;
    margin-bottom: 12px;
    color: #a0c4ff;
    letter-spacing: 1px;
  }
  #controls {
    display: flex;
    gap: 10px;
    margin-bottom: 14px;
  }
  button {
    background: #16213e;
    color: #a0c4ff;
    border: 1px solid #0f3460;
    padding: 8px 20px;
    font-size: 0.95rem;
    border-radius: 6px;
    cursor: pointer;
    transition: background 0.2s, transform 0.1s;
  }
  button:hover {
    background: #0f3460;
    transform: translateY(-1px);
  }
  button:active {
    transform: translateY(0);
    background: #1a1a5e;
  }
  #sim {
    border: 2px solid #0f3460;
    border-radius: 8px;
    cursor: crosshair;
    background: #0d1117;
    display: block;
  }
  #info {
    margin-top: 10px;
    font-size: 0.8rem;
    color: #666;
  }
</style>
</head>
<body>
<h1>Bouncing Ball Playground</h1>
<div id="controls">
  <button id="drop">Drop</button>
  <button id="play">Play</button>
  <button id="clear">Clear</button>
</div>
<canvas id="sim" width="500" height="500"></canvas>
<div id="info">Click canvas to add a ball</div>

<script>
(function() {
  const canvas = document.getElementById('sim');
  const ctx = canvas.getContext('2d');
  const W = canvas.width;
  const H = canvas.height;

  const GRAVITY = 0.4;
  const RESTITUTION = 0.85;

  let balls = [];
  let animating = false;
  let animId = null;

  const COLORS = [
    '#ff6b6b', '#ffd93d', '#6bcb77', '#4d96ff',
    '#ff6eb4', '#a66cff', '#00d2d3', '#ff9f43',
    '#ee5a24', '#0abde3', '#10ac84', '#f368e0'
  ];

  function randomColor() {
    return COLORS[Math.floor(Math.random() * COLORS.length)];
  }

  function createBall(x, y, vx, vy, r) {
    if (r === undefined || r === null) r = 12 + Math.random() * 10;
    return {
      x: x,
      y: y,
      vx: vx || 0,
      vy: vy || 0,
      r: r,
      color: randomColor()
    };
  }

  function draw() {
    ctx.clearRect(0, 0, W, H);

    // Draw subtle grid
    ctx.strokeStyle = 'rgba(255,255,255,0.03)';
    ctx.lineWidth = 1;
    for (let i = 0; i < W; i += 50) {
      ctx.beginPath();
      ctx.moveTo(i, 0);
      ctx.lineTo(i, H);
      ctx.stroke();
    }
    for (let i = 0; i < H; i += 50) {
      ctx.beginPath();
      ctx.moveTo(0, i);
      ctx.lineTo(W, i);
      ctx.stroke();
    }

    // Draw balls
    for (let i = 0; i < balls.length; i++) {
      const b = balls[i];

      // Shadow
      ctx.beginPath();
      ctx.arc(b.x + 2, b.y + 2, b.r, 0, Math.PI * 2);
      ctx.fillStyle = 'rgba(0,0,0,0.3)';
      ctx.fill();

      // Ball with gradient
      const grad = ctx.createRadialGradient(
        b.x - b.r * 0.3, b.y - b.r * 0.3, b.r * 0.1,
        b.x, b.y, b.r
      );
      grad.addColorStop(0, '#ffffff');
      grad.addColorStop(0.3, b.color);
      grad.addColorStop(1, darkenColor(b.color, 0.4));

      ctx.beginPath();
      ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2);
      ctx.fillStyle = grad;
      ctx.fill();

      // Highlight
      ctx.beginPath();
      ctx.arc(b.x - b.r * 0.25, b.y - b.r * 0.25, b.r * 0.3, 0, Math.PI * 2);
      ctx.fillStyle = 'rgba(255,255,255,0.25)';
      ctx.fill();
    }
  }

  function darkenColor(hex, factor) {
    let r = parseInt(hex.slice(1, 3), 16);
    let g = parseInt(hex.slice(3, 5), 16);
    let b = parseInt(hex.slice(5, 7), 16);
    r = Math.floor(r * (1 - factor));
    g = Math.floor(g * (1 - factor));
    b = Math.floor(b * (1 - factor));
    return '#' + r.toString(16).padStart(2, '0') + g.toString(16).padStart(2, '0') + b.toString(16).padStart(2, '0');
  }

  function stepPhysics(dt) {
    if (dt === undefined || dt === null) dt = 1;

    for (let i = 0; i < balls.length; i++) {
      const b = balls[i];

      // Apply gravity
      b.vy += GRAVITY * dt;

      // Update position
      b.x += b.vx * dt;
      b.y += b.vy * dt;

      // Bounce off left wall
      if (b.x - b.r < 0) {
        b.x = b.r;
        b.vx = -b.vx * RESTITUTION;
      }

      // Bounce off right wall
      if (b.x + b.r > W) {
        b.x = W - b.r;
        b.vx = -b.vx * RESTITUTION;
      }

      // Bounce off top wall
      if (b.y - b.r < 0) {
        b.y = b.r;
        b.vy = -b.vy * RESTITUTION;
      }

      // Bounce off bottom wall (floor)
      if (b.y + b.r > H) {
        b.y = H - b.r;
        b.vy = -b.vy * RESTITUTION;
      }

      // Final clamp to ensure never outside
      b.x = Math.max(b.r, Math.min(W - b.r, b.x));
      b.y = Math.max(b.r, Math.min(H - b.r, b.y));
    }
  }

  function step(dt) {
    if (dt === undefined || dt === null) dt = 1;
    stepPhysics(dt);
    draw();
  }

  function addBall(x, y, vx, vy, r) {
    if (vx === undefined) vx = 0;
    if (vy === undefined) vy = 0;
    const ball = createBall(x, y, vx, vy, r);
    balls.push(ball);
    draw();
    return ball;
  }

  function clearBalls() {
    balls = [];
    draw();
  }

  function getBalls() {
    return balls.map(function(b) {
      return { x: b.x, y: b.y, vx: b.vx, vy: b.vy, r: b.r };
    });
  }

  // Animation loop
  function animate() {
    if (!animating) return;
    stepPhysics(1);
    draw();
    animId = requestAnimationFrame(animate);
  }

  function togglePlay() {
    animating = !animating;
    const btn = document.getElementById('play');
    if (animating) {
      btn.textContent = 'Pause';
      animate();
    } else {
      btn.textContent = 'Play';
      if (animId) cancelAnimationFrame(animId);
    }
  }

  // Event listeners
  canvas.addEventListener('click', function(e) {
    const rect = canvas.getBoundingClientRect();
    const scaleX = W / rect.width;
    const scaleY = H / rect.height;
    const x = (e.clientX - rect.left) * scaleX;
    const y = (e.clientY - rect.top) * scaleY;
    addBall(x, y, (Math.random() - 0.5) * 4, -Math.random() * 3);
  });

  document.getElementById('drop').addEventListener('click', function() {
    const x = W * 0.2 + Math.random() * W * 0.6;
    addBall(x, 30, (Math.random() - 0.5) * 3, 0);
  });

  document.getElementById('play').addEventListener('click', togglePlay);

  document.getElementById('clear').addEventListener('click', function() {
    clearBalls();
  });

  // Expose API on window
  window.sim = {
    w: W,
    h: H,
    balls: getBalls,
    addBall: addBall,
    clear: clearBalls,
    step: step
  };

  // Initial draw
  draw();
})();
</script>
</body>
</html>
